### 4. How to Unit Test the Main Flow

Because all dependencies are injected via interfaces, unit testing `BenchmarkAssistantAgent` requires **no real network access, no monkey-patching of globals (`fetch`/`Date`), and zero external API keys**:

```typescript
import { describe, it, expect, vi } from "vitest";
import { BenchmarkAssistantAgent, ChatSession, IChatSession, ILLMClient, IClock, IIdGenerator } from "../index";

describe("BenchmarkAssistantAgent (Unit Tests)", () => {
  it("should dispatch message to client, record messages, and return response", async () => {
    // 1. Arrange: Create test doubles for session and LLM client
    const session = new ChatSession("test-session");
    const mockClient: ILLMClient = {
      getActiveProviderName: () => "MockLLMClient",
      setPrimaryProvider: vi.fn(),
      setFallbackProvider: vi.fn(),
      dispatchMessage: vi.fn(async (sess: IChatSession) => {
        return "Top recommendation is Gemini Exp 1206 with 2M context.";
      }),
    };

    // 2. Inject doubles directly via constructor
    const agent = new BenchmarkAssistantAgent({ session, client: mockClient });

    // 3. Act: Trigger the main flow
    const response = await agent.ask("Which model is the best?");

    // 4. Assert: Verify state changes and interactions
    expect(response).toBe("Top recommendation is Gemini Exp 1206 with 2M context.");
    expect(mockClient.dispatchMessage).toHaveBeenCalledTimes(1);
    expect(session.messages.length).toBe(2);
    expect(session.messages[0]).toMatchObject({ role: "user", content: "Which model is the best?" });
    expect(session.messages[1]).toMatchObject({ role: "assistant", content: response });
  });

  it("should handle client errors gracefully without throwing", async () => {
    const session = new ChatSession("test-error-session");
    const mockClient: ILLMClient = {
      getActiveProviderName: () => "FailingClient",
      setPrimaryProvider: vi.fn(),
      setFallbackProvider: vi.fn(),
      dispatchMessage: vi.fn(async () => {
        throw new Error("HTTP 429: Rate limit exceeded");
      }),
    };

    const agent = new BenchmarkAssistantAgent({ session, client: mockClient });
    const response = await agent.ask("Hello");

    expect(response).toContain("HTTP 429: Rate limit exceeded");
    expect(session.messages[1].content).toContain("HTTP 429: Rate limit exceeded");
  });
});
```

See [`src/core/__tests__/di.test.ts`](https://github.com/hubi666hubi/free-llm-api-benchmarks/blob/main/src/core/__tests__/di.test.ts) for the complete 13 unit tests covering container resolution, offline `GeminiProvider` mock HTTP dispatching, deterministic time mocking, and the main assistant flow. All 38 tests across the repository pass with full TypeScript type safety.
